  _ = `Bölüm Başlığı`,
  _ = `Bu bölümün üst kısmında görüntülenmesini istediğiniz başlığı hâlihazırda çevrilmiş başlıklar listesinden seçebilir ya da dilerseniz "özel başlık" seçeneğiyle kendi başlığınızı girebilirsiniz.`,
  _ = `Alt başlık`,
  _ = `(Azami %1$s karakter. Etkinlik veya duyuru detayları sayfasının en üstünde gösterilir.)`,
