  _ = `Yaratıcı ana sayfası v2 versiyonları; yayıncı, geliştirici veya seri sayfanızı özelleştirmek için esnek bir yol sunar.`,
  _ = `Bu sayfa görünür değildir. Önce sayfayı yayınlayın, ardından mevcut yaratıcı ana sayfanız olarak ayarlayabilirsiniz.`,
  _ = `Bu sayfa, mevcut yaratıcı ana sayfanız <1>değildir</1>. Değiştirmek için <2>yaratıcı ana sayfası panosunu</2> kullanın.`,
