  _ = `Hoş Geldiniz!`,
  _ = `<1>Oyunlarınız</1> - Oyunlarınız aşağıdaki İlişkilendirilmiş Uygulamalar Listesi'nde ve kullanıma hazır. Aşağıdan bölüm ekleyip yapılandirabilir ve böylece oyunlarınızı, DLC'lerinizi, demolarınızı ve oyun müziklerinizi ihtiyaçlarınıza en uygun şekilde satışa sunabilirsiniz.`,
  _ = `<1>Daha Fazla Oyun İlişkilendirmek</1> - Aşağıdaki listede eksik oyunlar varsa, oyunları bu yaratıcı ana sayfasıyla ilişkilendirmediğiniz anlamına gelir. Oyunları ana sayfanızla nasıl ilişkilendireceğinize ilişkin talimatlar için lütfen <2>Geliştirici ve Yayıncı Ana Sayfaları</2> belgesine danışın.`,
  _ = `<1>Varsayılan kurulum</1> - Aşağıda önceden yapılandırılmış varsayılan bölümler yer almaktadır. Bunlar popüler, önerilen ve son çıkan ürünlerinizi öne çıkarır. Varsayılan bölümleri dilediğiniz gibi kullanabilirsiniz.`,
  _ = `Daha fazla bilgi için ilgili belgeye göz atın`,
  _ = `Kategori: %1$s`,
  _ = `Etkinlik Klonlama Hatası`,
  _ = `Klonlama hazırlığı işleminde bir hata ile karşılaştık: %1$s`,
  _ = `Etkinlik Yayınlama Hatası`,
  _ = `Yayınlama etkinliği hazırlama işleminde bir hata ile karşılaştık: %1$s`,
  _ = `Bu indirimde çok geniş bir bağlantılı ürün listesi bulunduğundan, ürün etiketleri mağazadan alınarak yeniden oluşturuluyor. Bu işlem biraz zaman alabilir.`,
  _ = `Bu indirim için ürün etiketlerini mağazadan alıp yeniden oluşturamadığımızdan, düzenleyici güvenli bir şekilde açılamıyor. Lütfen sayfayı yeniden yükleyerek tekrar deneyin.`,
  _ = `Bağlantılı ürün listesindeki %1$s ürün, muhtemelen yasaklandığı veya artık satışta olmadığı için mağazadan yüklenemedi. Bu ürünlerin etiketleri yeniden oluşturulmadığı için etiket filtreli bölümlerden çıkarılabilirler (yasaklanmışlarsa veya benzer bir durumda normal şekilde devam edebilirsiniz): %2$s. `,
  _ = `Etkinlik Başlangıç Tarihi`,
  _ = `Duyuru Tarihi`,
  _ = `Şimdi - Etkinlik yayınlandığında`,
  _ = `Şimdi - Duyuru yayınlandığında`,
  _ = `Gelecekte - Etkinliği gelecekte başlamak üzere ayarlayın`,
  _ = `Gelecekte - Duyuruyu gelecekte görüntülenmek üzere ayarlayın`,
  _ = `Planlanan başlangıç tarihi`,
  _ = `Planlanan yayınlama tarihi`,
  _ = `Oyuncuları etkinliğin çıkış tarihinden haberdar etmek ve bildirim almaya abone olmalarına olanak tanımak için etkinliği başlangıç tarihinden önce görünür yapabilirsiniz.`,
  _ = `Oyuncuları etkinliğin çıkış tarihinden haberdar etmek ve bildirim almaya abone olmalarına olanak tanımak için duyuruyu başlangıç tarihinden önce görünür yapabilirsiniz.`,
  _ = `Etkinlik Bitiş Tarihi`,
  _ = `Bu kategoride yer alan etkinliklerin genellikle bir bitiş tarihi vardır.`,
  _ = `Bir bitiş tarihi seçin, böylece Steam etkinliğinizin ne zaman sona erdiğini belirtebilir. Bu sayede, Steam daha yakın tarihli olan veya o sırada gerçekleşen etkinliklerinizi göstermeye öncelik verir.`,
  _ = `Başlangıç tarihinden sonra belirtilen süre sonunda biter.`,
  _ = `Bitiş zamanı şuna denk geliyor: %1$s`,
  _ = `Bitiş Tarihi`,
  _ = `Düzenleyicideki etkinlik zamanları yerel saat diliminizde gösterilir. Etkinlikler, Steam müşterilerine de yerel saat dilimlerinde sunulur.`,
  _ = `Belirtilen zamanda sona ersin...`,
  _ = `Zamanları kendi yerel zaman diliminize göre girin. Zaman, oyuncuya kendi yerel zaman dilimine otomatik olarak çevrilerek gösterilir.`,
  _ = `Otomatik Hatırlatıcılar`,
  _ = `Bir etkinliği ileri tarihte başlayacak şekilde ayarlar VE hayranlarınıza önceden gösterirseniz, bu sayede hayranlarınız etkinlik başladığında bildirim almayı isteyebilir. Kullanıcıların tercihlerine göre Steam, onlara otomatik olarak bir bildirim ya da e-posta gönderir.`,
  _ = `Doğrulanmış bir e-posta adresiniz varsa ve/veya %1$s yüklüyse bu test hesabınıza bildirim gönderecek.`,
  _ = `Steam Mobil Uygulaması`,
  _ = `Test Etkinlik Bildirimi Gönder`,
  _ = `* Etkinlik ileri tarihli olmadığı için bu özellik devre dışıdır.`,
  _ = `İlişkili AppID`,
  _ = `AppID bu etkinlikle ilişkilendirilsin mi?`,
  _ = `Bu etkinlikle bir AppID ilişkilendirmeye izin verir. Bu, mağaza kapsülünün, etkinlik açıklamasının altında otomatik olarak gösterilmesine neden olur. Bu, uygulamanın verilerini gerektiğinde yayın veya takvim gibi diğer widget'lara da sağlayacaktır.`,
