  _ = `Derlemeyle İlişkilendir...`,
  _ = `Bu gönderinin Steam'deki ''İndirmeler'' penceresinde yama notu olarak görünmesi için bu gönderiyi belirli bir derlemeyle ilişkilendirin.`,
  _ = `Bu etkinlik herhangi bir derlemeyle ilişkilendirilmemiş.`,
