  _ = `Bu etkinlik şu derlemeyle ilişkilendirilmiş: %1$s (%2$s dalı)`,
  _ = `Dal Seç`,
  _ = `Bu etkinlikle ilişkilendirmek istediğiniz dalı seçin. Ardından bu etkinlik aynı zamanda ilgili daldaki en güncel derlemeyle ilişkilendirilmiş olur. Ayrıca, bir etkinliğin bir derlemeyle olan ilişkilendirmesini kaldırmak istiyorsanız "Bu etkinliği bir derlemeyle ilişkilendirme" seçeneğini seçebilirsiniz.`,
