  _ = `İptal`,
  _ = `Görsel Seç`,
  _ = `HTML'i içe aktar`,
  _ = `HTML'den içe aktar`,
  _ = `HTML'den içe aktar. HTML'iniz otomatik olarak Steam biçimlendirme etiketlerine dönüştürülür.`,
  _ = `Buraya HTML girin veya yapıştırın.`,
  _ = `Yeni satırları koru`,
  _ = `HTML'de satır sonunu boş bırakıp aşağı geçerseniz bu, sayfayı etkilemez, fakat BBCode'da satır sonları boşluk çizgileri şeklinde görülür. Eğer <p> veya <br> etiketleri kullandıysanız burayı işaretlemeyin. Eğer satır sonlarında kendiliğinden <br> etiketi bırakan bir blog yazılımı kullanıyorsanız, bu kutucuğu işaretlemek isteyebilirsiniz.`,
