  _ = `Çapraz Promosyon Arka Planı`,
  _ = `Çapraz Promosyon Arka Planı`,
  _ = `Bu indirimin çapraz promosyon bölümlerinin (örneğin, İndirimler ve Etkinlikler sayfası) arkasına yerleştirilir. Tüm diller için bir görsel kullanılır. Görsel, bölümün tamamını kenardan kenara kaplayacak ve bu alana sığacak şekilde kırpılacaktır, bu nedenle önemli öğeleri özellikle üst ve alt kenarlardan uzak tutun.`,
  _ = `minimum %1$s x %2$s piksel (genişlik x uzunluk)`,
  _ = `Arka Planı Kaldır`,
  _ = `Arka plan yüklenmedi.`,
  _ = `Masaüstünde logo ve oyunların nasıl düzenleneceğini seçin. Telefondan görüntülendiğinde logo her zaman oyunların üstünde yer alır.`,
  _ = `Masaüstü düzeni:`,
  _ = `Logo solda`,
