  _ = `Hedef:`,
  _ = `İndirim Sayfası URL'i:`,
  _ = `Sadece https://store.steampowered.com/ ile başlayan geçerli bir URL'in girilmesini destekliyoruz.`,
  _ = `Mağaza indirimi sayfası URL'ini değiştir`,
  _ = `Bu URL geçerli değil ya da https://store.steampowered.com/ ile başlamıyor.`,
  _ = `Gerekli: Metin başlığını buraya girin`,
  _ = `Gerekli: Metin gövdesinin kopyasını buraya girin`,
  _ = `Merhaba %1$s,`,
  _ = `<username>`,
  _ = `Bu e-postayı şunu oynadığınız için alıyorsunuz:`,
  _ = `Bu e-postayı Steam'de %1$s adlı oyunu takip ettiğiniz için alıyorsunuz.`,
  _ = `Bu e-postayı %1$s serisindeki bir oyunu oynadığınız için alıyorsunuz.`,
  _ = `Bu e-postayı Steam'de %1$s adlı oyunu istek listenize eklediğiniz için alıyorsunuz.`,
  _ = `Şu oyunu oynadığınız için bu etkinlik bildirimi e-postasını alıyorsunuz:`,
  _ = `Şu oyunu takip ettiğiniz için bu etkinlik bildirimi e-postasını alıyorsunuz:`,
  _ = `Şu serideki bir oyunu oynadığınız için bu etkinlik bildirimi e-postasını alıyorsunuz:`,
  _ = `Şu oyunu istek listenize eklediğiniz için bu etkinlik bildirimi e-postasını alıyorsunuz:`,
  _ = `%1$s Steam'de`,
  _ = `Gelecekte oyuna özel bildirim e-postaları almak istemiyorsanız`,
  _ = `%1$s hakkındaki e-postaları yok sayabilir`,
  _ = `veya`,
  _ = `e-posta tercihlerinizi düzenleyerek abonelikten çıkabilirsiniz`,
  _ = `© Valve Corporation.  PO Box 1688 Bellevue, WA 98009.`,
  _ = `Tüm hakları saklıdır. Tüm ticari markalar, ABD ve diğer ülkelerde ilgili sahiplerinin mülkiyetindedir.`,
  _ = `Deneme E-postasını Gönder`,
  _ = `Deneme e-postası gönderilemedi. E-postanız Steam'de onaylanmamış. Lütfen şuradan onaylayın: %1$s`,
  _ = `E-postada yapılan değişiklikler kaydedilmedi. E-postayı ön izlemeden önce yaptığınız değişiklikleri lütfen kaydedin.`,
  _ = `E-posta hesabınızla ilişkili olan "%1$s" adresine gönderilsin mi? Bu bilgi yanlışsa lütfen şuradan e-posta adresinizi güncelleyin: %2$s`,
  _ = `Markalaşma Görüntüsünü Seçin`,
  _ = `%1$s x %2$s piksel`,
  _ = `Hesap Filtreleri`,
  _ = `Seçilen her kullanıcı, bildirimi almak için bu filtrelerin koşullarını sağlamalıdır.`,
  _ = `Uygulama, Steam Tavsiye Sistemi'nin tavsiyelerinde ilk N'inci`,
  _ = `Oyunu istek listesine ekleyen kullanıcıları hariç tut`,
  _ = `Bildirimlerin gönderilmeyeceği kontrol grubu`,
  _ = `Alıcılar`,
  _ = `Bu e-posta kimlere gitmeli?`,
  _ = `Oyununuzun mevcut oyuncularına`,
  _ = `Oyununuzu istek listesine ekleyenlere`,
  _ = `Oyununuzun takipçilerine`,
  _ = `Oyununuza sahip olanları dahil etme`,
  _ = `Oynama süresine sahip olmayan müşteriler`,
  _ = `%1$s yaratıcı ana sayfanızı takip eden takipçilere`,
  _ = `%1$s yaratıcı ana sayfanıza bağlı oyunları oynayan oyunculara gönder`,
  _ = `Bu oyunla ilişkilendirilmiş bir yaratıcı ana sayfası olmadığı için e-posta potansiyeli kısıtlandı. Daha fazlasını öğrenmek için şuraya gidin: %1$s`,
  _ = `%1$s dili için ilgili içerik eksik. %3$s kısmın toplam %2$s kısmı tamamlanmış.`,
  _ = `E-postada İngilizce markalaşma çizimi olmalıdır. E-posta, İngilizce çizim olmadan gönderilemez.`,
  _ = `Bu e-postayı alacak en az bir alıcı grubu seçmelisiniz`,
  _ = `Bu e-postada metin yok`,
  _ = `Alıcı kısmında en azından geliştirici ya da yayıncı haklarından birini seçmelisiniz.`,
  _ = `YouTube URL'i girilmiş ancak bu çözümlenemiyor. Lütfen video URL'ini kontrol edin.`,
  _ = `İlgili etkinlik yayınlanıp herkese açılana kadar e-postalar ayarlanamaz ve gönderilemez. Lütfen öncelikle etkinliği yayınlayın.`,
  _ = `E-posta %1$s yerelleştirmesine sahip ancak bu yerelleştirme için ilgili markalaşma çizimi yok. Çizim olmadığı takdirde İngilizce markalaşma çizimi kullanılır.`,
  _ = `E-posta %1$s ve %2$s yerelleştirmesine sahip ancak bu yerelleştirmeler için ilgili markalaşma çizimleri yok. Çizim olmadığı takdirde İngilizce markalaşma çizimi kullanılır.`,
  _ = `E-posta %1$s, %2$s ve %3$s farklı dilde daha yerelleştirmeye sahip ancak bu yerelleştirmeler için ilgili markalaşma çizimleri yok. Çizim olmadığı takdirde İngilizce markalaşma çizimi kullanılır.`,
  _ = `E-posta %1$s dilinde yerelleştirmeye sahip ancak bu dil için markalaşma çizimi yok.`,
  _ = `E-posta Hazırlanıyor`,
  _ = `Bu etkinlikte kaydedilmemiş değişiklikler var. Bu e-postayı göndermeden önce lütfen etkinlikteki değişiklikleri kaydedin.`,
  _ = `E-posta gönderilmeye hazır. E-postayı kilitleyerek daha fazla değişiklik yapılmasını engellemeye hazır mısınız? Bu, e-postayı göndermez sadece göndermeye hazır olduğunuz zaman göndermeye hazır olacak şekilde tutar.`,
  _ = `Şu uyarılarla karşılaştık. E-posta içeriğini kilitlemeden önce isteğe bağlı olarak bu uyarıları düzeltebilirsiniz.`,
  _ = `E-postayı hazırlarken, gönderimini engelleyecek şu hatalarla karşılaştık:`,
