  _ = `AppID'leri Ekle`,
  _ = `Yayıncı Ekle`,
  _ = `Bu mesaj, aşağıda seçtiğiniz izinlerden HERHANGİ BİRİNE sahip olan kullanıcılara gönderilecek. En azından bir tane izin seçmelisiniz.`,
  _ = `Yayıncı Yetkileri`,
  _ = `Uygulama Yetkileri`,
