  _ = `Veya özel başlık ile geçersiz kılın`,
  _ = `Bu yayıncıyı izin verilenler listesinden kaldırın.`,
  _ = `Kullanıcılara ilk olarak yüksek önceliğe sahip hesapların yaptığı yayınlar gösterilir.`,
  _ = `Başlık ekle`,
  _ = `Başlığı kaydet`,
