  _ = `Etiket adı girin (boşluksuz)`,
  _ = `Bu ayarlanırsa, tüm oyunlar (bu indirimde açıkça yer almayanlar bile) döngüsel görüntüleyiciye dahil edilir. Kullanıcının ilgilendiği (sahip olduğu, istek listesinde bulunan, takip ettiği) oyunlardan etkinlikleri tercih ediyoruz. Bunlardan sonra ise yedek olarak en çok satan oyunlara yer veriyoruz.`,
  _ = `Yüklenecek Maksimum Etkinlik`,
