  _ = `Steam China için Bağlantı URL'i`,
  _ = `Sadece store.steampowered.com ve steamcommunity.com adreslerindeki konumlar geçerlidir. URL eklediğinizde, bu görsele tıklayan kullanıcılar mağazadaki veya topluluktaki başka bir konuma yönlendirilir.`,
  _ = `Hata: https://store.steampowered.com/ veya https://steamcommunity.com/ ile başlamalıdır.`,
  _ = `Sadece store.steamchina.com adresindeki konumlar geçerlidir. URL eklediğinizde, bu görsele tıklayan kullanıcılar mağazadaki başka bir konuma yönlendirilir.`,
