  _ = `Başlık bölümü, metin veya görselden oluşabilir ve takip eden içerik için bir etiket görevi görür. Sekmeler bölümüyle birlikte kullanıldığında, iki veya daha fazla sekme mevcutsa, isteğe bağlı olarak otomatik alt sekme seçenekleri sağlayabilir. Sekme işlevselliği için aşağıya kısa bir ad girilmesi gereklidir.`,
