  _ = `Başlık`,
  _ = `Alt Başlık`,
  _ = `Sekme alt menüsü kısa adı`,
  _ = `Bunun Sekmeler alt menüsünde görünmesini istiyorsanız kısa bir ad verin. Alt menünün Sekmeler bölümünden ayrıca etkinleştirilmesi gerekir.`,
  _ = `Görsel Ekle`,
