  _ = `Yeni Bölüm Ekle`,
  _ = `İçerik Bölümü Ekle`,
  _ = `Oyun adları, etkinlikler, metinler, afişler, canlı yayınlar veya diğer içerikleri ekleyebileceğiniz özelleştirilebilir yeni bir bölüm yaratıp ekleyin. Sayfanızdaki içerikleri düzenlemek ve göstermek için birden fazla bölüm kullanın.`,
  _ = `Filtrelenenleri Sil`,
  _ = `Bu, an itibarıyla filtrelenmiş bütün ilişkilendirilmiş öğeleri siler. Bu, indirim boyutunu küçültmeye yardımcı olabilir ve indirim sayfasını daha etkin ve kullanımı daha kolay bir hâle getirebilir.`,
  _ = `Katılım Sayfası Adı`,
  _ = `Katılım sayfasının adı, katılım sayfasındaki öğelerin içe aktarılmasını sağlar. Örnek: "sale_fighting".`,
  _ = `Seçilen Öğeleri Senkronize Et`,
  _ = `Bu, seçilen yeni katılım sayfasını öğelerini ekleyecek ve artık katılım sayfasında olmayan öğeleri ilişkilendirilmiş öğeler listesinden kaldıracaktır. Yeni öğelere varsayılan mağaza ve katılım indirim etiketleri eklenir.`,
  _ = `Katılım Sayfası Damgalarını Senkronize Et`,
