  _ = `Mağaza Etiketlerini Senkronize Et`,
  _ = `Bu, bu indirimde listelenen ilişkilendirilmiş öğeler için tüm mağaza etiketlerini yeniden senkronize edecektir (Örnek: Aksiyon veya Birinci Şahıs).`,
  _ = `Özellik Damgalarını Senkronize Et`,
