  _ = `Uygulama Türü Damgalarını Senkronize Et`,
  _ = `Bu, bu indirimde listelenen tüm ilişkilendirilmiş öğelerin DLC veya demo gibi uygulama türü damgalarının tamamını yeniden senkronize edecektir.`,
  _ = `Senkronizasyon görünür mağaza sayfası olan oyunları gerektirsin`,
  _ = `Bu etkinleştirildiğinde, yayınlanmış bir mağaza sayfası olmayan ve dolayısıyla Steam mağazasında görünmeyen oyunlardan veri çekilmeyecek.`,
  _ = `İçe Aktar`,
  _ = `(Valve'a Özel) İndirim Etkinliği Yarat veya Güncelle`,
  _ = `Zaman aralığı yapılandırması ve bu aralık için partner tarafından sağlanan indirimlerin belirlenmesini gerektiren bir indirim etkinliği oluşturmaya olanak sağlar.`,
  _ = `Kaydet ve İndirim Etkinliği Yarat`,
  _ = `Kaydet ve İndirim Etkinliğini Güncelle: %1$s`,
  _ = `Seçim kriterleri:`,
  _ = `Kişiselleştirilmiş: İstek listesine eklenen oyunlar`,
  _ = `Bu sayfadaki oyunlar VE sayfayı görüntüleyen kullanıcının istek listesindeki oyunlar gösterilecek.`,
  _ = `Kişiselleştirilmiş: Oynama süresine göre önerilenler`,
  _ = `Bu sayfadaki oyunlar VE Steam tarafından kullanıcı için seçilen en iyi 150 oyun önerisi gösterilecek. Yalnızca çıkmış oyunlar için geçerlidir.`,
  _ = `Kişiselleştirilmiş: Tek bir favori etiketle eşleşen oyunlar`,
  _ = `Bunların her biri, kullanıcıların en çok oynadığı oyunların etiketlerinden birine ait oyunları gösterecektir. İlki en çok oynanan oyunların etiketini gösterecek, ikincisi bir sonraki etiketi gösterecek vb.`,
  _ = `Kişiselleştirilmiş: Etiketlere göre önerilenler`,
  _ = `Kullanıcının yakın zamanda oynadığı oyunlara benzer etiketlere sahip oyunlar gösterilecek. Henüz çıkmamış oyunlar da dâhil olabilir.`,
  _ = `Popülerliğe göre sıralanmış indirimli oyunlar`,
