  _ = `<Görüntülemek için bir liste seçin>`,
  _ = `Belirtilen listedeki oyunlar görüntülenir. Bunu yaratıcı ana sayfası panosunda yapılandırabilirsiniz. Bu, Yaratıcı Listesi bölüm türünü seçmekle aynıdır.`,
  _ = `%1$s (Gizli)`,
  _ = `Öne çıkanlar listesi filtresi`,
