  _ = `Bu indirim sayfasını, Yaratıcı Ana Sayfası listelerinizden birinde bulunan uygulamalarla sınırlandırın. Ayarlandığında, yalnızca listede bulunan ve Yaratıcı Ana Sayfanıza hâlâ bağlı olan uygulamalar öne çıkarılır. Yaratıcı Ana Sayfanızdaki tüm uygulamaları öne çıkarmak için ayarı boş bırakın.`,
  _ = `Tüm uygulamalar (filtresiz)`,
  _ = `Yaratıcı Ana Sayfası Listesi Seç…`,
  _ = `İndirim sayfasını bir listeyle sınırlandırın`,
