  _ = `Bu listede şu anda Yaratıcı Ana Sayfanıza bağlı hiçbir uygulama bulunmadığı için bağlantı kurulana kadar indirim sayfasında hiçbir uygulama öne çıkarılmayacak.`,
  _ = `Farklı bir uygulama setini mi öne çıkarmak istiyorsunuz? Yaratıcı Ana Sayfası panonuzda <1>liste oluşturun veya listelerinizi yönetin</1>.`,
