  _ = `İsteğe bağlı olarak, kullanıcı tüm sorulara doğru cevap verdikten sonra gösterilecek bir BBCode'u aşağıya ekleyebilirsiniz. Bu kısım aynı zamanda son sorudan hemen sonra görünür.`,
