  _ = `Tablo öğelerini yeniden boyutlandırır. 2 veya 3 tablo öğesi içeren satırlarda, tek bir tablo öğesi büyütülerek diğer tablo öğelerinin buna bağlı olarak küçültülmesi sağlanabilir. Bu tablo öğesini küçültmek için tıklayın.`,
