  _ = `Görsel bölümleri görsellerin daha kolay yerelleştirilmesine olanak tanır ve müşterilere sunulan son indirim sayfasında daha hızlı işlenir. Ayrıca başlık görseli bölümünde kullanılan görseller görsel seçiciyi karıştırmaz.`,
  _ = `Sosyal Medya Paylaşımı İçerik Ön İzlemesi`,
  _ = `Bu, sosyal medya platformlarında etkinliğin bağlantısı verildiğinde veya paylaşıldığında içeriğin nasıl görüneceğinin bir ön izlemesidir.`,
