  _ = `Bu indirim için ilişkilendirilmiş öğelerin doğrudan düzenlenmesine izin verir. Bu, Excel gibi araçlardan içeri veya dışarı aktarma yapmak ya da bir dizi öğeye büyük değişiklikler yapmak için kullanılabilir.`,
  _ = `Özel Damgalar`,
  _ = `Bu indirim için ilişkilendirilmiş öğeler listesini doğrudan düzenlemeye ve sadece indirim öğelerinin üzerindeki damga koleksiyonlarını içe ve dışa aktarmaya olanak sağlar. Bu birincil olarak harici bir tablo aracılığıyla yönetilen özel damgaların yer aldığı listeleri, öğelerdeki diğer damgaları değiştirmeden içe aktarmak için kullanılır. Buna ek olarak bu işlem listelenmemiş öğeleri silmeyeceğinden bu işlem kullanılarak bir alt küme de içe aktarılabilir.`,
  _ = `Katılma Sayfasından İçe Aktar`,
