  _ = `Keşfet`,
  _ = `Filtreleme aracını, yapılandırılmış mevcut ilişkilendirilmiş öğelerden hangilerinin farklı filtrelere uyduğunu veya hangi damgalara sahip olduğunu keşfetmek için kullanmaya olanak tanır.`,
