  _ = `İçe aktarmak istediğiniz içerik türünü seçin. Her bir ID'yi farklı satıra girin.`,
  _ = `Uyarı: Seçenekler sekmesinde "Steam Mağazası Ürün Sayfamda Göster" kapalı olduğu için afiş, Steam mağazasında gösterilmeyecek.`,
  _ = `Bu bölümü satış sayfasından kaldırmak istediğinizden emin misiniz?`,
  _ = `Etkinlik açıklaması başka bir bölümde zaten gösterilecek. Burada da görünmesini istediğinizden emin misiniz?`,
