  _ = `Yalnızca %1$s. Günün Öğeleri (%2$s)`,
  _ = `Yeni öğeler için görünürlük`,
  _ = `Belirtilen öğelerin indirimin hangi gününde öne çıkarılacağını belirler. Varsayılan olarak bunlar her gün gösterilir fakat bunu kullanarak belirli öğeleri indirimin belirli günlerinde görünecek şekilde sınırlayabilirsiniz.`,
  _ = `Günlük İndirim Arka Planları`,
  _ = `Varsayılan, tüm indirim etkinliği için tek bir başlık arka planı anlamına gelir. Bir üst seçenek, farklı günlerde farklı çizimlerin gösterilmesine izin verir. Daha sonra son günün çizimi gösterilmeye devam eder. Kullanılabilir arka plan sayısı, seçenekler sekmesinde etkinlik için belirtilmiş gün sayısına bağlıdır.`,
  _ = `%1$s İndirim Başlığı`,
  _ = `Tüm etkinlik için tek indirim başlık çizimi`,
  _ = `Bu ayarı değiştirirseniz önceden seçilen tüm indirim başlık çizimleri, bu etkinlikten kaldırılacak. Devam etmek istiyor musunuz?`,
  _ = `Hangi günün çizimini görüntülüyoruz/güncelliyoruz?`,
  _ = `Önizlemede, seçili gün için yüklenen çizim gösteriliyor. Başlık ile ilişkili tüm çizimler, şeçtiğiniz mevcut güne de uygulanacaktır.`,
  _ = `Yalnızca %1$s. günde, %2$s ile %3$s arasında görünür`,
  _ = `%1$s. gün %2$s itibarıyla görünür`,
  _ = `veya`,
  _ = `İçerdiği Öğeler`,
  _ = `Bu bölümde gösterilecek öğelerin belirlenmesine ve isteğe bağlı olarak gösterilecek günün seçilmesine olanak tanır.`,
  _ = `İçerdiği Öğeler`,
  _ = `Yukarıda belirlenen filtreler sonucu gösterilen öğeler.`,
  _ = `Tekrarlı`,
  _ = `Bu öğe, aynı bölümde bir veya daha fazla gün boyunca birden fazla gösterilecek şekilde ayarlandı.`,
  _ = `Bu etkinliği eklemek istediğinizden emin misiniz? Bu etkinlik listede zaten yer alıyor.`,
  _ = `Sonuç Bulunamadı`,
  _ = `(%1$s %2$s) için sonuç bulunamadı. Yazım yanlışı yapılmış olabilir; ancak aradığınız şey bölgenizde görünmez veya gizli de olabilir`,
  _ = `İzin verilmiyor`,
  _ = `Bu öğe, bu indirim sayfasının yaratıcı ana sayfasına (Geliştirici, Yayıncı veya Seri) bağlı olmadığı için eklenemiyor. Öğeyi bağlayın ve ilişkilendirmeyi yenilemek için indirim sayfasını yeniden yükleyin.`,
  _ = `Pakete İzin Verilmiyor`,
  _ = `Bu paket, bu indirim sayfasının yaratıcı ana sayfasına (Geliştirici, Yayıncı veya Seri) bağlı olmadığı için eklenemiyor. Öğeyi bağlayın ve ilişkilendirmeyi yenilemek için indirim sayfasını yeniden yükleyin. Şu uygulamalar yaratıcıyla ilişkilendirilmemiş: (%1$s)`,
  _ = `Demete İzin Verilmiyor`,
  _ = `Bu demet, bu indirim sayfasının yaratıcı ana sayfasına (Geliştirici, Yayıncı veya Seri) bağlı olmadığı için eklenemiyor. Öğeyi bağlayın ve ilişkilendirmeyi yenilemek için indirim sayfasını yeniden yükleyin. Şu uygulamalar yaratıcıyla ilişkilendirilmemiş: (%1$s)`,
  _ = `Bu etkinlik geçmiş bir etkinlikten kopyalandı. Bu indirim sayfasını yapılandırabilmeniz için indirim sayfası özelliğinin Valve tarafından etkinleştirilmesi gereklidir.`,
  _ = `Çapraz Promosyon İndirim Sayfası`,
  _ = `İndirim etkinliği GID'sini gir`,
  _ = `Bu, partner etkinlik düzenleyicisi adresinin sonunda yer alan benzersiz ID'dir. Sadece indirim sayfası GID'si kullanılmalıdır. Bu adıma dair detaylar için belgeye göz atın.`,
  _ = `https://steamcommunity.com/groups/<grup adı>/partnerevents/edit/<Bu GID'yi al>`,
  _ = `Geçersiz GID girildi; yalnızca sayısal bir değer olmalıdır`,
  _ = `İndirim sayfasına bağlantı verildi.`,
  _ = `Etkinlik mevcut fakat buna giden bir bağlantı şu anda üretilemiyor. İndirim teknolojisi etkinleştirilmediğinden veya hiç oyun eklenmediğinden bağlantı için gerekli dâhili ID eksik. Lütfen organizatörlerden indirim sayfasını ayarlamalarını isteyin ve bağlantıyı tekrar deneyin.`,
  _ = `İndirim Sayfası Bilgileri Yükleniyor`,
  _ = `İndirim sayfası henüz yayınlanmadı ve görünür değil.`,
  _ = `İndirim Sayfası Başlığı: %1$s`,
  _ = `Bu indirim sayfasında etkinlik kapsül görseli yok.`,
  _ = `Uygulama Seçimi`,
  _ = `İstek Listelerine Eklenme Sayılarına Öncelik Ver`,
  _ = `Çapraz promosyonu yapılan indirim sayfası büyük oranda çıkacak oyunlara sahipse bu, bu oyunların gelir verileri olmayacağı anlamına gelir ve bu durumda istek listelerine eklenme sayılarına öncelik vermek iyi olacaktır.`,
  _ = `Gelire Öncelik Ver`,
  _ = `Bu varsayılandır. Çapraz promosyonu yapılan indirim sayfasında kullanıcılara gösterilecek oyunları belirlemede satış sayılarını kullanır.`,
  _ = `İndirim sayfası sayısı birden fazla olduğunda, bu bölüm her indirim sayfası için bir slayt içeren bir karusel hâline gelir ve slaytlar bu sırayla görüntülenir. Sürükleyerek sırayı değiştirebilirsiniz.`,
  _ = `Başka Bir İndirim Sayfası Ekle`,
  _ = `Sınırlı Stok Düzenleyicisi`,
  _ = `Sınırlı Stok Seçeneği Ekle`,
  _ = `Açıklamayı Düzenle`,
  _ = `Açıklama Altındaki Kısmı Düzenle`,
  _ = `Açıklamayı Buraya Girin`,
  _ = `Ürünlerin etrafında gösterilecek kısa açıklamayı düzenleyin.`,
  _ = `Donanım Paketi`,
  _ = `Kullanıcının bu bloktan satın aldığı donanım paketi.`,
  _ = `Bu seçeneği bir görsel veya tahminî teslimat tarihi olmadan yalnızca paket adı, fiyat ve "Satın Al" butonundan oluşan tek bir satır halinde görüntülemek için açıklama kısmını boş bırakın.`,
  _ = `Düzen`,
  _ = `Tablo görünümü, sabit genişlikteki blokları satırlar halinde sıralar. Liste görünümü ise her satırda tek bir blok gösterir ve resmi metnin yanına yerleştirir.`,
  _ = `Tablo`,
  _ = `Liste`,
  _ = `Tükenen paketleri gizle`,
  _ = `Bu seçenek etkinleştirildiğinde, stokta olmayan paketler için "Tükendi" butonu görüntülenmez. Bunun yerine ilgili paket bölümden kaldırılır. Seçenek varsayılan olarak devre dışıdır.`,
  _ = `Kompakt satır renkleri`,
  _ = `Bunlar, tek bir satır olarak görüntülenen ve açıklaması olmayan seçenekler için geçerlidir. "Varsayılan" olarak bırakılan tüm öğeler standart görünümlerini koruyacaktır.`,
  _ = `Ad`,
  _ = `Kutu arka planı`,
  _ = `Fiyat`,
  _ = `Satın alma butonu`,
  _ = `Satın alma butonu metni`,
  _ = `Varsayılan`,
