  _ = `Oval`,
  _ = `(Sadece Valve İçin) Nitelikler`,
  _ = `(Sadece Valve İçin) Niteliklere Göre Göz Atma`,
  _ = `Kullanıcıların bu kısımdaki öğeleri filtrelemesine ve aramasına olanak tanır. NOT: Bunu etkinleştirmek, bu bölümdeki tüm öne çıkan öğeleri kaldıracaktır.`,
  _ = `Ad`,
  _ = `Alt Başlık (İsteğe Bağlı)`,
  _ = `Etiket`,
  _ = `Nitelik Değeri Ekle`,
  _ = `Nitelik Ekle`,
  _ = `%1$s Nitelik`,
  _ = `%1$s Nitelik Değerleri`,
  _ = `Nitelikleri Otomatik Üret`,
  _ = `Üret`,
  _ = `Mevcut niteliklerin üzerine yazılsın mı?`,
  _ = `Otomatik üretilen nitelikler bu kısımdaki mevcut niteliklerin üzerine yazılacak. Devam etmek istiyor musunuz?`,
  _ = `"Kontrolcü" mağaza etiketine sahip uygulamalar için ana özellik damgasını kullanın.`,
  _ = `Kullanılmayan Nitelikleri Sil`,
  _ = `Sil`,
  _ = `Nitelik değerleriyle eşleşen minimum kapsül`,
  _ = `Önerilen değer: 5`,
  _ = `Nitelik başına maksimum nitelik değeri`,
  _ = `Önerilen değer: 5`,
  _ = `Nitelik değerlerini sırala`,
  _ = `Ada göre`,
  _ = `Eşleşme sayısına göre`,
  _ = `Manuel`,
  _ = `Bu nitelik değerinin adı. Nitelik değeri, kullanıcının bu bölümde gösterilen oyunları filtreleyebileceği bireysel bir seçenektir. Örneğin, "Birinci Şahıs".`,
  _ = `Bu nitelik değerinin sağında gösterilen isteğe bağlı metin. Bunu, nitelik değerinin kısa bir açıklamasını sağlamak üzere kullanın. Örneğin, kısa oynanış süresine sahip oyunlar için nitelik değeri olarak "1-2 saat" girmek gibi.`,
  _ = `Bu niteliğin adı. Nitelik, birbiriyle ilişkili seçeneklerden oluşan bir gruptur. Kullanıcı bunların her birine tıklayarak bu bölümde gösterilen oyunları filtreleyebilir. Örneğin, "tür".`,
  _ = `Nitelikleri ve nitelik değerlerini mağaza etiketi kategorilerine göre (örneğin "Tür" ve "Görseller ve Perspektif") otomatik olarak doldurur. Otomatik olarak oluşturan nitelikleri ve nitelik değerlerini sonradan manuel olarak düzenleyebilirsiniz.`,
  _ = `Bu kısımdaki öğelerden hiçbiriyle eşleşmeyen nitelik değerlerini kaldırın.`,
  _ = `Seçilmiş bir nitelik için en az kaç tane sonuç istiyorsunuz? Bu, en az belirtmiş olduğunuz sayı kadar sonuca sahip olmayan terimleri gizler. Bir terimle eşleşen sonuç sayısı, sekme filtreleri uygulandıktan sonra hesaplanır. Bunu 5 civarında bir sayı olarak belirlemek iyi olacaktır.`,
  _ = `Sol menüde herhangi bir üst kategorinin altında maksimum bu sayıda seçeneği gösterin. Örneğin, "Tür" adındaki niteliğin altında belirttiğinizden daha fazla seçenek göstermeyin. 5 genellikle iyi bir sınırdır.`,
  _ = `Her nitelikte, nitelik değerleri bu ölçüte göre sıralanır. En iyisi genellikle eşleşme sayısına göredir.`,
  _ = `Her nitelikte, nitelik değerlerinin adları alfabetik olarak sıralanır.`,
  _ = `Her nitelik içinde, nitelik değerleri kendileriyle eşleşen öğe sayısına göre azalarak sıralanır. Örneğin "Tür" niteliği altında "RYO" oyunları "Strateji" oyunlarından fazlaysa RYO, Strateji'den önce gösterilir.`,
  _ = `Nitelik değerleri sıralanmaz. Aşağıdaki listelerde tanımlanan sırada gösterilir.`,
  _ = `Vurgulanmış Nitelik Rengi`,
  _ = `Başlık Rengi`,
  _ = `Varsayılan olarak etkindir`,
  _ = `En popüler 20 mağaza etiketini senkronize et`,
  _ = `Varsayılan olarak, her bir öğe için sadece en popüler 10 mağaza etiketi senkronize edilir. En popüler 10 yerine 20 mağaza etiketini senkronize etmek için bu kutucuğu işaretleyin.`,
  _ = `Hata ayıklama için bilgi oluştur`,
  _ = `Cebirsel VE operatörü`,
  _ = `İşaretlenirse kullanıcı bu façetada birden çok façeta değeri seçtiğinde, seçilen façeta değeri filtrelerinin cebirsel VE değeri uygulanır. Aksi takdirde, seçilen façeta değeri filtrelerinin cebirsel VEYA değeri uygulanır.`,
  _ = `Başlangıçta genişlet`,
  _ = `Bu seçenek işaretlenirse bu nitelik, tarayıcı ilk açıldığında genişletilir.`,
  _ = `Tek seçim`,
  _ = `Bu seçenek işaretlenirse bu nitelik değerini seçmek diğer seçimleri kaldırır.`,
  _ = `Öğe Kaynağı Ayarları (İsteğe Bağlı)`,
  _ = `İlişkilendirilmiş uygulamaların bir listesini belirtmek yerine, bu indirim etkinliği için öğelerin getirileceği bir içerik merkezinin adını belirtebilirsiniz. Belirtilirse, bu indirim için ilişkilendirilmiş uygulama listesi yok sayılır ve indirim sayfası, belirtilen içerik merkezindekileri gösterir.`,
  _ = `İçerik Merkezi Türü`,
  _ = `Kategori`,
  _ = `Etiket`,
  _ = `Sadece indirimli ve oynaması ücretsiz öğeleri göster`,
  _ = `Öğe Kaynağı`,
