  _ = `İçerik Merkezi Ana Karuseli`,
  _ = `İçerik Merkezi İkincil Karuselleri`,
  _ = `Öğe Tanımı (sanal öğeler)`,
  _ = `Envanter hizmeti veya partnere ait oyuna özgü ekonomik varlıklar hizmeti tarafından yönetilen oyuna özgü sanal öğeler.`,
  _ = `Seçili Sanal Öğeler:`,
  _ = `İzin verilen maksimum adet`,
  _ = `Bu türden sanal öğelerden tek seferde en fazla kaç adet alınabileceğinin sayısı. Açılır adet menüsünü devre dışı bırakmak için sıfır veya bir olarak ayarlayın.`,
  _ = `Uygulamanın Öğe Mağazasını Görüntüle`,
  _ = `Sanal Öğe Ekle`,
  _ = `Sanal öğeyle ilişkilendirilmiş varsayılan çizimi geçersiz kılmak için yükleme yapmayı tercih edebilirsiniz. Aksi takdirde, öğe mağazasında sanal eşya için gösterilecek görseli kullanırız`,
  _ = `Ücretsiz Öğeyi Al`,
  _ = `Kullanıcının ücretsiz zaman hakkını almasına izin veren bir bölüm. Bir sonraki öğe (varsa) alınabilir olduğunda gösterilir. Günlük öğe düşürmeleri için kullanılabilir. İndirim öğelerini yapılandırmak için ödül widget'ıyla ilişkilendirilmiştir.`,
  _ = `İsteğe Bağlı: Al butonu adı girin`,
  _ = `Girilmediği takdirde varsayılan buton adını kullanırız.`,
  _ = `Kişisel Takvim`,
  _ = `İstek listesine eklenmiş ve tavsiye edilen yakında çıkacak oyunların belirli bir gün aralığında gösterildiği bölüm.`,
  _ = `Gün Sayısı`,
  _ = `İleriye veya geriye dönük olarak gösterilecek gün sayısı.`,
  _ = `Yükseklik`,
  _ = `Bir hafta içinde (ileriye dönük olarak) veya kapsül sıralarında (geriye dönük olarak) dikey olarak gösterilecek maksimum kapsül sayısı.`,
  _ = `Yön`,
  _ = `Takvimin bugünden itibaren ileriye dönük (çıkmamış oyunlar) veya geriye dönük (çıkmış oyunlar) gösterileceğini belirler.`,
  _ = `İleriye Dönük`,
  _ = `Geriye Dönük`,
  _ = `SSS`,
  _ = `Sorular cevaplarıyla birlikte görüntülenir. Sorular art arda veya yan yana görünür.`,
  _ = `Teknik Özellikler Listesi`,
  _ = `Teknik özellikler ayrı bir bölümde gösterilir ve her özellik ayrı bir madde olarak sunulur.`,
  _ = `Medya İçerikleri Tablosu`,
  _ = `Açıklamalı medya öğelerinden oluşan özelleştirilebilir bir tablo. Satır başına en fazla 5 sütun olmak üzere istediğiniz sayıda satır ekleyebilirsiniz. Her satırdaki sütun sayısı farklı olabilir.`,
  _ = `Medya Katmanı`,
  _ = `Ana odak noktası medya öğeleri (videolar/görseller) olup, görsel üzerine metin yerleştirme olanağı bulunmaktadır.`,
  _ = `Steam İncelemeleri`,
  _ = `Steam'deki bir uygulamanın incelemelerini göster ve müşterilerin inceleme yazmasına izin ver.`,
  _ = `Sizin için DLC'ler`,
  _ = `Kullanıcının kütüphanesindeki tüm uygulumalardan DLC'leri gösterir. Bu kısım sadece indirim sayfasında listelenen veya öğe listesinde bağlantısı verilmiş öğelerle sınırlı kalmaz, tüm Steam kataloğunu göz önünde bulundurur.`,
  _ = `Filtre`,
  _ = `Popüler`,
  _ = `DLC'leri satış sıralamasına göre artan bir sırada gösterir.`,
  _ = `Yeni Çıkanlar`,
  _ = `DLC'leri en yeni çıkan başta olacak şekilde çıkış tarihlerine göre sıralanmış bir şekilde gösterir.`,
  _ = `Pek Yakında`,
  _ = `Yakında çıkacak DLC'leri gösterir.`,
