  _ = `Ücretsiz DLC'leri gösterir.`,
  _ = `Ana Uygulamaya Göre Gruplandır`,
  _ = `Her ana uygulama için ayrı bir karuselde olacak şekilde ilişkili DLC'leri gösterir.`,
  _ = `Ana Uygulamaları Sırala`,
  _ = `Oynama Süresi`,
  _ = `Ana uygulamaları, en çok oynanan ilk sırada olacak şekilde toplam oynanma süresine göre sıralar.`,
  _ = `Son Oynama`,
  _ = `Ana uygulamaları, en son oynanan ilk sırada olacak şekilde son oynanma tarihine göre sıralar.`,
  _ = `Popüler`,
  _ = `Önce en popüler DLC'lere sahip ana uygulamaları gösterir. Popülerlik satış sıralamalarına bağlı olduğundan, düşük satış sıralamasında olan DLC'ler gösterilmeyebilir.`,
  _ = `Son Oynamadan Bu Yana Geçen Maks. Süre (ay)`,
  _ = `Sadece gösterilen ay sayısı kadar önceden bu yana kullanıcı tarafından oynanmış oyunlara ait DLC'leri gösterir.`,
  _ = `Min. Oynama Süresi (saat)`,
  _ = `Sadece en az gösterilen saat sayısı süresince bu kullanıcı tarafından oynanmış oyunlara ait DLC'leri gösterir.`,
  _ = `Gösterilecek Ana Uygulamalar`,
  _ = `Sayfa yüklendiğinde, yalnızca belirtilen maksimum sayıda oyuna ait DLC'leri gösterir. Daha fazla oyun için DLC varsa, ''Daha Fazla'' butonu çıkar.`,
  _ = `DLC İstatistiklerini Gizle`,
  _ = `Seçildiğinde, kullanıcının sahip olduğu ve kullanabildiği DLC'nin istatistik özeti bu bölümün en üstünde gösterilmez.`,
