  _ = `Üzgünüz, bu sayfayı bulamadık.`,
  _ = `Panoya Git`,
  _ = `Metninizin başlığı ve ana kısmı için içe aktarılacak bir veya daha fazla yerelleştirme metni seçin ve yükleyin. Dosyanın XML mi CSV mi olduğunu tespit etmek için dosya uzantısını kullanıyoruz. XML dosyasının içerik diline karar vermek için dosya adının sonunda ve uzantıdan önce bulunan API dil kodunu kullanıyoruz. Doğru formatı kullandığınızdan emin olmak için önce CSV veya XML'i dışa aktarmalısınız.`,
  _ = `Mevcut dili seçili dosya türünde tek bir dosya olarak dışarı aktarır. XML her zaman mevcut düzenleyici diliyle bir XML dosyası oluşturur. CSV, bütün dilleri tek bir dosyada toplar.`,
  _ = `Görseller`,
  _ = `SSS'yi Düzenle`,
  _ = `SSS'yi Sil…`,
  _ = `Bu SSS'yi kalıcı olarak siler.`,
  _ = `Bu SSS girdisi hemen silinir ve bu işlem geri alınamaz. Bu makaleyi ve buna ait bütün yerelleştirilmiş içerikleri silmek istediğinize emin misiniz?`,
  _ = `SSS siliniyor, lütfen bekleyin.`,
  _ = `Silme işlemi tamamlandı. Bu pencereyi kapatıp panoya geri dönebilirsiniz.`,
  _ = `Görünürlüğü Değiştir`,
  _ = `Düzenle…`,
  _ = `Bu SSS'yi istediğiniz bölgelerde görünür yapmak için buradaki seçenekler arasından seçim yapın. Görünür olması için istenilen dilde yayınlanmış bir sürümü veya bölgeye uygun yedek bir sürümü olmalıdır.`,
  _ = `SSS bölge görünürlüğü bu pencere aracılığıyla değiştirilebilir. Görünür olmayan bir doküman yayınlansa bile erişilebilir olmaz.`,
  _ = `SSS'nin görünürlük ayarı güncelleniyor.`,
  _ = `Görünürlük ayarı güncellendi.`,
  _ = `Steam Global'da görünür`,
  _ = `Steam China'da Görünür`,
  _ = `Not: İçeriğin Steam China'da görünebilir olması için Basitleştirilmiş Çince veya Geleneksel Çince dillerinde yerelleştirilmiş ve Steam China'da yayınlanmış olması gereklidir.`,
  _ = `Canlı SSS'yi Görüntüle`,
  _ = `Dahili SSS Adını Değiştir`,
  _ = `Dahili SSS adına yapılan değişiklik (düzenleyici olmayan kullanıcılara görünmez) "Tamam"a bastıktan sonra hemen uygulanacak.`,
  _ = `Yayınla…`,
  _ = `Bir veya daha fazla dildeki taslağı herkese açık sürümle değiştirir. Görünürlüğün yayınlanan sürümlerden ayrı olarak kontrol edildiğini unutmayın.`,
  _ = `Yayınlama işlemine başlamadan önce kaydetmeniz gereklidir.`,
