  _ = `Yayınlama tamamlandı.`,
  _ = `Yayınladığınız zaman taslak sürüm yayınlanmış sürüm hâline gelir. Aşağıdaki dillerin taslaklarında değişiklikler var. Hangilerini yayınlamak istediğinizi seçin.`,
  _ = `Not: Bir SSS'nin yayınlanması ve görünürlüğü birbirinden bağımsızdır. Steam bölgesi görünürlüğünü ayrıca ayarlamanız gereklidir.`,
  _ = `Yükleme hatası. Dokümanı yayınlamak için gerekli olan önceki yayınlama bilgileri eksik. Sayfayı yeniden yükleyin.`,
